import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary, lateFee } from '../src/reports.js';
import { createInvoice, issueInvoice, lineTotal, lineDiscount, lineVAT, invoiceTotals } from '../src/invoices.js';
import { recordPayment, balanceDue } from '../src/payments.js';

test('overdueInvoices rejects invalid asOf date', () => {
  const result = overdueInvoices([], 'not-a-date');
  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('overdueInvoices returns empty array when no invoices', () => {
  const result = overdueInvoices([], '2025-10-07');
  assert.equal(result.ok, true);
  assert.deepEqual(result.value, []);
});

test('overdueInvoices excludes draft invoices', () => {
  const draftResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result = overdueInvoices([draftResult.value], '2025-10-07');
  assert.equal(result.ok, true);
  assert.deepEqual(result.value, []);
});

test('overdueInvoices excludes paid invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const balanceResult = balanceDue(invoice);
  const paidResult = recordPayment(invoice, { amount: balanceResult, date: '2025-10-02' });

  const result = overdueInvoices([paidResult.value], '2025-10-07');
  assert.equal(result.ok, true);
  assert.deepEqual(result.value, []);
});

test('overdueInvoices excludes invoices with future due dates', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);

  const result = overdueInvoices([issuedResult.value], '2025-10-05');
  assert.equal(result.ok, true);
  assert.deepEqual(result.value, []);
});

test('overdueInvoices includes issued invoices with past due dates', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const result = overdueInvoices([invoice], '2025-11-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.length, 1);
  assert.equal(result.value[0].number, invoice.number);
});

test('overdueInvoices includes partially_paid invoices with past due dates', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const paymentResult = recordPayment(invoice, { amount: 10000, date: '2025-10-02' });

  const result = overdueInvoices([paymentResult.value], '2025-11-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.length, 1);
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const result = overdueInvoices([invoice], '2025-11-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.length, 1);
  assert.equal(result.value[0].daysOverdue, 10);
});

test('overdueInvoices returns due amount from balanceDue', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const expected = balanceDue(invoice);

  const result = overdueInvoices([invoice], '2025-11-10');
  assert.equal(result.ok, true);
  assert.equal(result.value[0].due, expected);
});

test('overdueInvoices returns due amount after partial payment', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const paymentResult = recordPayment(invoice, { amount: 10000, date: '2025-10-02' });
  const expected = balanceDue(paymentResult.value);

  const result = overdueInvoices([paymentResult.value], '2025-11-10');
  assert.equal(result.ok, true);
  assert.equal(result.value[0].due, expected);
});

test('overdueInvoices includes invoiceNumber and customerId', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const result = overdueInvoices([invoice], '2025-11-10');
  assert.equal(result.ok, true);
  assert.equal(result.value[0].number, invoice.number);
  assert.equal(result.value[0].customerId, 'C-001');
});

test('overdueInvoices includes dueDate', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const result = overdueInvoices([invoice], '2025-11-10');
  assert.equal(result.ok, true);
  assert.equal(result.value[0].dueDate, invoice.dueDate);
});

test('overdueInvoices sorts by daysOverdue descending', () => {
  const invoice1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const issued1 = issueInvoice(invoice1Result.value, []);

  const invoice2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const issued2 = issueInvoice(invoice2Result.value, ['INV-2025-0001']);

  const result = overdueInvoices([issued1.value, issued2.value], '2025-11-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.length, 2);
  assert(result.value[0].daysOverdue > result.value[1].daysOverdue);
});

test('overdueInvoices handles mix of issued and partially_paid invoices', () => {
  const invoice1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const issued1 = issueInvoice(invoice1Result.value, []);

  const invoice2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-02',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const issued2 = issueInvoice(invoice2Result.value, ['INV-2025-0001']);
  const partial = recordPayment(issued2.value, { amount: 10000, date: '2025-10-03' });

  const result = overdueInvoices([issued1.value, partial.value], '2025-11-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.length, 2);
});

test('vatSummary returns empty array when no invoices', () => {
  const result = vatSummary([]);
  assert.equal(result.ok, true);
  assert.deepEqual(result.value, []);
});

test('vatSummary excludes draft invoices', () => {
  const draftResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result = vatSummary([draftResult.value]);
  assert.equal(result.ok, true);
  assert.deepEqual(result.value, []);
});

test('vatSummary includes issued invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);

  const result = vatSummary([issuedResult.value]);
  assert.equal(result.ok, true);
  assert(result.value.length > 0);
});

test('vatSummary includes partially_paid invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const paymentResult = recordPayment(issuedResult.value, { amount: 10000, date: '2025-10-02' });

  const result = vatSummary([paymentResult.value]);
  assert.equal(result.ok, true);
  assert(result.value.length > 0);
});

test('vatSummary includes paid invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const totals = invoiceTotals(issuedResult.value);
  const paymentResult = recordPayment(issuedResult.value, { amount: totals.total, date: '2025-10-02' });

  const result = vatSummary([paymentResult.value]);
  assert.equal(result.ok, true);
  assert(result.value.length > 0);
});

test('vatSummary calculates base correctly (lineTotal - discount)', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;
  const line = invoice.lines[0];

  const expectedBase = lineTotal(line) - lineDiscount(line);

  const result = vatSummary([invoice]);
  assert.equal(result.ok, true);
  const entry = result.value.find(e => e.rate === line.vatRate);
  assert(entry);
  assert.equal(entry.base, expectedBase);
});

test('vatSummary calculates vat correctly', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;
  const line = invoice.lines[0];

  const expectedVat = lineVAT(line);

  const result = vatSummary([invoice]);
  assert.equal(result.ok, true);
  const entry = result.value.find(e => e.rate === line.vatRate);
  assert(entry);
  assert.equal(entry.vat, expectedVat);
});

test('vatSummary groups by VAT rate', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'PRINT-A4', qty: 12 },
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const result = vatSummary([invoice]);
  assert.equal(result.ok, true);

  const devLine = invoice.lines.find(l => l.sku === 'DEV-HOUR');
  const printLine = invoice.lines.find(l => l.sku === 'PRINT-A4');

  if (devLine.vatRate !== printLine.vatRate) {
    assert(result.value.length >= 2);
  }
});

test('vatSummary accumulates base and vat from multiple lines with same rate', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const expectedBase = lineTotal(invoice.lines[0]) - lineDiscount(invoice.lines[0]) + lineTotal(invoice.lines[1]) - lineDiscount(invoice.lines[1]);
  const expectedVat = lineVAT(invoice.lines[0]) + lineVAT(invoice.lines[1]);

  const result = vatSummary([invoice]);
  assert.equal(result.ok, true);
  const entry = result.value.find(e => e.rate === invoice.lines[0].vatRate);
  assert(entry);
  assert.equal(entry.base, expectedBase);
  assert.equal(entry.vat, expectedVat);
});

test('vatSummary sorts by rate descending', () => {
  const invoice1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoice1Result.ok, true);
  const issued1 = issueInvoice(invoice1Result.value, []);

  const invoice2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-01',
    lines: [{ sku: 'PRINT-A4', qty: 12 }],
  });

  assert.equal(invoice2Result.ok, true);
  const issued2 = issueInvoice(invoice2Result.value, ['INV-2025-0001']);

  const result = vatSummary([issued1.value, issued2.value]);
  assert.equal(result.ok, true);

  for (let i = 0; i < result.value.length - 1; i++) {
    assert(result.value[i].rate >= result.value[i + 1].rate);
  }
});

test('vatSummary handles invoices with multiple VAT rates', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'PRINT-A4', qty: 12 },
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const result = vatSummary([invoice]);
  assert.equal(result.ok, true);

  const devLine = invoice.lines.find(l => l.sku === 'DEV-HOUR');
  const printLine = invoice.lines.find(l => l.sku === 'PRINT-A4');

  if (devLine.vatRate === printLine.vatRate) {
    assert.equal(result.value.length, 1);
  } else {
    assert.equal(result.value.length, 2);
    assert.equal(result.value[0].rate, Math.max(devLine.vatRate, printLine.vatRate));
  }
});

test('vatSummary includes rate field', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const result = vatSummary([invoice]);
  assert.equal(result.ok, true);
  assert(result.value.length > 0);
  assert('rate' in result.value[0]);
