test('lateFee rejects invalid asOf date', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const result = lateFee(invoice, 'not-a-date');
  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('lateFee returns 0 when invoice is not overdue', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const result = lateFee(invoice, '2025-10-30');
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('lateFee returns 0 when due date equals asOf', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const result = lateFee(invoice, invoice.dueDate);
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('lateFee calculates fee for 1 day overdue', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const due = balanceDue(invoice);
  const daysOverdue = 1;
  const expectedFee = Math.round(due * 0.0004 * daysOverdue);

  const result = lateFee(invoice, '2025-11-01');
  assert.equal(result.ok, true);
  assert.equal(result.value, expectedFee);
});

test('lateFee calculates fee for 10 days overdue', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const due = balanceDue(invoice);
  const daysOverdue = 10;
  const expectedFee = Math.round(due * 0.0004 * daysOverdue);

  const result = lateFee(invoice, '2025-11-10');
  assert.equal(result.ok, true);
  assert.equal(result.value, expectedFee);
});

test('lateFee returns 0 for fully paid invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const totals = invoiceTotals(invoice);
  const paymentResult = recordPayment(invoice, { amount: totals.total, date: '2025-10-02' });

  const result = lateFee(paymentResult.value, '2025-11-10');
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('lateFee calculates fee on remaining balance for partially paid invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const payment = recordPayment(invoice, { amount: 10000, date: '2025-10-02' });
  const remainingDue = balanceDue(payment.value);
  const daysOverdue = 10;
  const expectedFee = Math.round(remainingDue * 0.0004 * daysOverdue);

  const result = lateFee(payment.value, '2025-11-10');
  assert.equal(result.ok, true);
  assert.equal(result.value, expectedFee);
});

test('lateFee fee is always a whole number of cents', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const result = lateFee(invoice, '2025-11-10');
  assert.equal(result.ok, true);
  assert(Number.isInteger(result.value));
});

test('lateFee is clamped at 0', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const result = lateFee(invoice, '2025-11-10');
  assert.equal(result.ok, true);
  assert(result.value >= 0);
});

test('lateFee fee increases with days overdue', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const fee5Days = lateFee(invoice, '2025-11-05');
  const fee10Days = lateFee(invoice, '2025-11-10');

  assert.equal(fee5Days.ok, true);
  assert.equal(fee10Days.ok, true);
  assert(fee10Days.value > fee5Days.value);
});

test('lateFee fee is proportional to days overdue', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const fee5Days = lateFee(invoice, '2025-11-05');
  const fee10Days = lateFee(invoice, '2025-11-10');
  const fee20Days = lateFee(invoice, '2025-11-20');

  assert.equal(fee5Days.ok, true);
  assert.equal(fee10Days.ok, true);
  assert.equal(fee20Days.ok, true);

  assert(fee5Days.value > 0);
  assert(Math.abs(fee10Days.value - fee5Days.value * 2) <= 1);
  assert(Math.abs(fee20Days.value - fee5Days.value * 4) <= 1);
});

