test('dashboard returns top 3 customers sorted by amount due', () => {
  const customers = ['C-001', 'C-002', 'C-003'];
  const quantities = [15, 10, 5];
  const invoices = [];

  for (let i = 0; i < customers.length; i++) {
    const invoiceResult = createInvoice({
      customerId: customers[i],
      issueDate: '2025-10-01',
      lines: [{ sku: 'DEV-HOUR', qty: quantities[i] }],
    });
    const issued = issueInvoice(invoiceResult.value, invoices.map(inv => inv.number || ''));
    invoices.push(issued.value);
  }

  const result = dashboard(invoices, '2025-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.topCustomers.length, 3);
  assert.equal(result.value.topCustomers[0].customerId, 'C-001');
  assert.equal(result.value.topCustomers[1].customerId, 'C-002');
  assert.equal(result.value.topCustomers[2].customerId, 'C-003');
  assert(result.value.topCustomers[0].due >= result.value.topCustomers[1].due);
  assert(result.value.topCustomers[1].due >= result.value.topCustomers[2].due);
});

