test('vatSummary accumulates base and vat from multiple lines with same rate', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const expectedBase = lineTotal(invoice.lines[0]) - lineDiscount(invoice.lines[0]) + lineTotal(invoice.lines[1]) - lineDiscount(invoice.lines[1]);
  const expectedVat = lineVAT(invoice.lines[0]) + lineVAT(invoice.lines[1]);

  const result = vatSummary([invoice]);
  assert.equal(result.ok, true);
  const entry = result.value.find(e => e.rate === invoice.lines[0].vatRate);
  assert(entry);
  assert.equal(entry.base, expectedBase);
  assert.equal(entry.vat, expectedVat);
});

