  assert.equal(result.ok, true);

  const devLine = invoice.lines.find(l => l.sku === 'DEV-HOUR');
  const printLine = invoice.lines.find(l => l.sku === 'PRINT-A4');

  if (devLine.vatRate === printLine.vatRate) {
