test('lateFee fee is proportional to days overdue', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;

  const fee5Days = lateFee(invoice, '2025-11-05');
  const fee10Days = lateFee(invoice, '2025-11-10');
  const fee20Days = lateFee(invoice, '2025-11-20');

  assert.equal(fee5Days.ok, true);
  assert.equal(fee10Days.ok, true);
  assert.equal(fee20Days.ok, true);

  assert(fee5Days.value > 0);
  assert(Math.abs(fee10Days.value - fee5Days.value * 2) <= 1);
  assert(Math.abs(fee20Days.value - fee5Days.value * 4) <= 1);
});
